WITH flattened AS (SELECT id, customer_id, created_at, coupon_codes, line.product_id FROM carts LATERAL VIEW OUTER EXPLODE(items) li AS line), enriched AS (SELECT src.customer_id, src.product_id, d.segment, d.city, d.signup_date FROM flattened src LEFT JOIN customers d ON src.customer_id <=> d.id WHERE d.is_active), joined AS (SELECT a.customer_id, a.product_id, a.city, a.signup_date, p.email, p.signup_date AS customer_signup_date, p.country FROM enriched a INNER JOIN customers p ON a.customer_id = p.id), with_windows AS (SELECT *, COUNT(product_id) OVER (PARTITION BY country) AS country_count_product_id, RANK() OVER (PARTITION BY city, customer_id ORDER BY product_id DESC) AS product_id_rank, CUME_DIST() OVER (ORDER BY product_id DESC) AS product_id_cume_dist FROM joined), with_dims AS (SELECT e.customer_id, e.product_id, e.city, e.email, e.country, e.country_count_product_id, p.country AS customer_country, p.name FROM with_windows e LEFT JOIN customers p ON e.customer_id = p.id), with_windows_carts AS (SELECT email, country_count_product_id, customer_country, name, PERCENT_RANK() OVER (ORDER BY country_count_product_id DESC NULLS FIRST) AS country_count_product_id_percent_rank, ROUND(product_id / SUM(product_id) OVER (PARTITION BY country, city), 4) AS product_id_share FROM with_dims) SELECT customer_country, COUNT(*) FILTER (WHERE customer_country = 'JP') AS jp_rows, COUNT(*) FILTER (WHERE customer_country = 'DE') AS de_rows, COUNT_IF(customer_country = 'US') AS us_events FROM with_windows_carts GROUP BY customer_country HAVING jp_rows > 1
